import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"Building and development","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/development.md","filePath":"en/shitbot/development.md"}'),n={name:"en/shitbot/development.md"};function l(o,e,d,r,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="building-and-development" tabindex="-1">Building and development <a class="header-anchor" href="#building-and-development" aria-label="Permalink to &quot;Building and development&quot;">​</a></h1><p>This page is for developers building or modifying ShitBot. Server owners should download published JARs from <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">GitHub Releases</a>.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><ul><li>JDK 21.</li><li>Maven 3.8 or newer.</li><li>Access to Maven Central and the Spigot, BungeeCord, Velocity, and Nukkit-MOT dependency repositories.</li></ul><p>The aggregate project builds with JDK 21 and produces:</p><table tabindex="0"><thead><tr><th>Module</th><th>Bytecode target</th></tr></thead><tbody><tr><td>ShitBotApi</td><td>Java 8</td></tr><tr><td>ShitBotCore</td><td>Java 8</td></tr><tr><td>ShitBotRenderer</td><td>Java 8</td></tr><tr><td>ShitBotSpigot</td><td>Java 8</td></tr><tr><td>ShitBotBungee</td><td>Java 8</td></tr><tr><td>ShitBotVelocity</td><td>Java 21</td></tr><tr><td>ShitBotNukkit</td><td>Java 17</td></tr></tbody></table><h2 id="build-all-platforms" tabindex="-1">Build all platforms <a class="header-anchor" href="#build-all-platforms" aria-label="Permalink to &quot;Build all platforms&quot;">​</a></h2><p>From the repository root:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package</span></span></code></pre></div><p>The <code>revision</code> property in <code>.mvn/maven.config</code> supplies the version. To override it:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Drevision</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SNAPSHOT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package</span></span></code></pre></div><h2 id="build-one-platform" tabindex="-1">Build one platform <a class="header-anchor" href="#build-one-platform" aria-label="Permalink to &quot;Build one platform&quot;">​</a></h2><p>Use <code>-am</code> to also build the required ShitBotApi and ShitBotCore modules:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotSpigot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotBungee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotVelocity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotNukkit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span></code></pre></div><p>Final plugin JARs are in each module&#39;s <code>target/</code>. Do not distribute <code>original-*.jar</code>, sources, javadoc, or test JARs as plugins.</p><h2 id="module-structure" tabindex="-1">Module structure <a class="header-anchor" href="#module-structure" aria-label="Permalink to &quot;Module structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShitBot/</span></span>
<span class="line"><span>├─ ShitBotApi/        # Binding, whitelist, image API and rendering SPI; published separately</span></span>
<span class="line"><span>├─ ShitBotCore/       # OneBot, database, binding, images, updates, and shared logic</span></span>
<span class="line"><span>├─ ShitBotRenderer/   # Separately published, optional Java2D scene renderer and editor</span></span>
<span class="line"><span>├─ ShitBotSpigot/     # Bukkit, Paper, Folia, and backend command listener</span></span>
<span class="line"><span>├─ ShitBotBungee/     # BungeeCord entry point</span></span>
<span class="line"><span>├─ ShitBotVelocity/   # Velocity entry point</span></span>
<span class="line"><span>├─ ShitBotNukkit/     # Nukkit-MOT entry point</span></span>
<span class="line"><span>├─ PictureBridge/    # Git submodule for the separate client mod</span></span>
<span class="line"><span>├─ docs/             # Chinese documentation and English translations in en/</span></span>
<span class="line"><span>└─ pom.xml           # Maven aggregate project</span></span></code></pre></div><p>Platform modules depend on ShitBotCore and relocate the shared runtime dependencies into the final JAR. Platform APIs use <code>provided</code> scope and should not be bundled. <code>ShitBotRenderer</code> must not become a platform module dependency: it is loaded in isolation at runtime through the ShitBotApi SPI, preserving the small default plugin and optional download behavior.</p><h2 id="configuration-resources" tabindex="-1">Configuration resources <a class="header-anchor" href="#configuration-resources" aria-label="Permalink to &quot;Configuration resources&quot;">​</a></h2><p>Platform defaults are in:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShitBotSpigot/src/main/resources/</span></span>
<span class="line"><span>ShitBotBungee/src/main/resources/</span></span>
<span class="line"><span>ShitBotVelocity/src/main/resources/</span></span>
<span class="line"><span>ShitBotNukkit/src/main/resources/</span></span></code></pre></div><p>When changing configuration structure, consider:</p><ul><li>All four <code>config.yml</code> files.</li><li>The applicable <code>commands.yml</code> files.</li><li>Shared Core <code>lang/zh_CN.yml</code> and <code>lang/en_US.yml</code>.</li><li>Shared Core <code>templates/default.yml</code>.</li><li>Loaders and default values.</li><li>Reload behavior.</li><li>Configuration examples in the documentation.</li></ul><p>Nukkit-MOT has no proxy/backend transport configuration. Other platforms share the same <code>commands.yml</code> structure.</p><h2 id="picturebridge-submodule" tabindex="-1">PictureBridge submodule <a class="header-anchor" href="#picturebridge-submodule" aria-label="Permalink to &quot;PictureBridge submodule&quot;">​</a></h2><p>PictureBridge has its own repository and build. It is not part of ShitBot&#39;s Maven aggregate project. You do not need to build it when only modifying the server plugin.</p><p>For client development, initialize the submodule after cloning:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git submodule update </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">init </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">recursive</span></span></code></pre></div><p>See PictureBridge&#39;s own documentation for build instructions.</p><h2 id="ci-and-releases" tabindex="-1">CI and releases <a class="header-anchor" href="#ci-and-releases" aria-label="Permalink to &quot;CI and releases&quot;">​</a></h2><p>On pushes, pull requests, and manual runs, GitHub Actions:</p><ol><li>Runs <code>mvn clean package</code> with JDK 21.</li><li>Collects four platform JARs, one ShitBotApi JAR, and one separate ShitBotRenderer JAR.</li><li>Generates SHA-256 files.</li><li>Uploads workflow artifacts.</li></ol><p>For GitHub releases, the workflow also:</p><ol><li>Signs all four platform JARs, the public API JAR, and the optional renderer JAR with the RSA private key in repository secrets.</li><li>Checks for six JARs, six checksums, and six signatures.</li><li>Uploads the JARs, <code>.sha256</code>, and <code>.sig</code> files.</li></ol><p>See <a href="/docs/en/shitbot/updating.html">Upgrading and automatic updates</a> for signing key management.</p><h2 id="release-documentation" tabindex="-1">Release documentation <a class="header-anchor" href="#release-documentation" aria-label="Permalink to &quot;Release documentation&quot;">​</a></h2><p>For releases with configuration changes, explain in the release notes:</p><ul><li>Whether <code>config.yml</code> needs regeneration or new entries.</li><li>Whether proxies and backends must update together.</li><li>Whether the database schema changes.</li><li>Whether Java or platform minimums change.</li><li>Whether new permissions, ports, or external network dependencies are introduced.</li></ul><h2 id="maintaining-both-documentation-languages" tabindex="-1">Maintaining both documentation languages <a class="header-anchor" href="#maintaining-both-documentation-languages" aria-label="Permalink to &quot;Maintaining both documentation languages&quot;">​</a></h2><p>Chinese documentation lives in <code>README.md</code> and <code>docs/*.md</code>. English documentation lives in <code>README.en.md</code> and <code>docs/en/*.md</code>, using the same manual filenames. Keep the language links at the top of each page and update both versions when behavior changes.</p><p>The website&#39;s <code>npm run docs:sync -- ../ShitBot</code> command copies both manuals into the corresponding Chinese and English sections. Shared template examples remain in <code>docs/examples/</code>.</p>`,41)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
